Here is the commit message:
gtp: Fix inconsistent indenting

Fix the following warning as reported by smatch:

New smatch warnings:
drivers/net/gtp.c:1796 gtp_genl_send_echo_req() warn: inconsistent indenting

Fixes: d33bd757d362 ("gtp: Implement GTP echo request")
Reported-by: kernel test robot <lkp@intel.com>
Signed-off-by: Wojciech Drewek <wojciech.drewek@intel.com>
Signed-off-by: Tony Nguyen <anthony.l.nguyen@intel.com>

Here is the root cause:
The bug was caused by inconsistent indentation in the `gtp_genl_send_echo_req()` function, which can lead to confusion in code readability and maintenance, potentially causing developers to misinterpret the code structure and logic flow.

Here is the patch:

 static int gtp_genl_send_echo_req(struct sk_buff *skb, struct genl_info *info)
 {
 	struct sk_buff *skb_to_send;
 	__be32 src_ip, dst_ip;
 	unsigned int version;
 	struct gtp_dev *gtp;
 	struct flowi4 fl4;
 	struct rtable *rt;
 	struct sock *sk;
 	__be16 port;
 	int len;

 	if (!info->attrs[GTPA_VERSION] ||
 	    !info->attrs[GTPA_LINK] ||
 	    !info->attrs[GTPA_PEER_ADDRESS] ||
 	    !info->attrs[GTPA_MS_ADDRESS])
 		return -EINVAL;

 	version = nla_get_u32(info->attrs[GTPA_VERSION]);
 	dst_ip = nla_get_be32(info->attrs[GTPA_PEER_ADDRESS]);
 	src_ip = nla_get_be32(info->attrs[GTPA_MS_ADDRESS]);

 	gtp = gtp_find_dev(sock_net(skb->sk), info->attrs);
 	if (!gtp)
 		return -ENODEV;

 	if (!gtp->sk_created)
 		return -EOPNOTSUPP;
 	if (!(gtp->dev->flags & IFF_UP))
 		return -ENETDOWN;

 	if (version == GTP_V0) {
 		struct gtp0_header *gtp0_h;

 		len = LL_RESERVED_SPACE(gtp->dev) + sizeof(struct gtp0_header) +
 			sizeof(struct iphdr) + sizeof(struct udphdr);

 		skb_to_send = netdev_alloc_skb_ip_align(gtp->dev, len);
 		if (!skb_to_send)
 			return -ENOMEM;

 		sk = gtp->sk0;
 		port = htons(GTP0_PORT);

 		gtp0_h = skb_push(skb_to_send, sizeof(struct gtp0_header));
 		memset(gtp0_h, 0, sizeof(struct gtp0_header));
 		gtp0_build_echo_msg(gtp0_h, GTP_ECHO_REQ);
 	} else if (version == GTP_V1) {
 		struct gtp1_header_long *gtp1u_h;

 		len = LL_RESERVED_SPACE(gtp->dev) +
 			sizeof(struct gtp1_header_long) +
 			sizeof(struct iphdr) + sizeof(struct udphdr);

 		skb_to_send = netdev_alloc_skb_ip_align(gtp->dev, len);
 		if (!skb_to_send)
 			return -ENOMEM;

 		sk = gtp->sk1u;
 		port = htons(GTP1U_PORT);

 		gtp1u_h = skb_push(skb_to_send,
 				   sizeof(struct gtp1_header_long));
 		memset(gtp1u_h, 0, sizeof(struct gtp1_header_long));
 		gtp1u_build_echo_msg(gtp1u_h, GTP_ECHO_REQ);
 	} else {
 		return -ENODEV;
 	}

 	rt = ip4_route_output_gtp(&fl4, sk, dst_ip, src_ip);
 	if (IS_ERR(rt)) {
 		netdev_dbg(gtp->dev, "no route for echo request to %pI4\n",
 			   &dst_ip);
-			   kfree_skb(skb_to_send);
+		kfree_skb(skb_to_send);
 		return -ENODEV;
 	}

 	udp_tunnel_xmit_skb(rt, sk, skb_to_send,
 			    fl4.saddr, fl4.daddr,
 			    fl4.flowi4_tos,
 			    ip4_dst_hoplimit(&rt->dst),
 			    0,
 			    port, port,
 			    !net_eq(sock_net(sk),
 				    dev_net(gtp->dev)),
 			    false);
 	return 0;
 }



